<style>.sc-calc-head{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}.sc-calc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.sc-calc-key{min-height:46px;font-size:18px}.sc-tool{padding:8px 0}.sc-repeat-row{display:grid;grid-template-columns:repeat(5,minmax(90px,1fr)) 38px;gap:8px;align-items:end;margin-bottom:10px;padding:10px;border:1px solid #ddd;border-radius:6px;background:#fafafa}.sc-repeat-row .form-group{margin:0}.sc-history{max-height:250px;overflow:auto;border:1px solid #ddd;padding:8px}.sc-history div{padding:5px;border-bottom:1px solid #eee;cursor:pointer}@media(max-width:767px){.sc-repeat-row{grid-template-columns:1fr 1fr}.sc-calc-head .btn-group{display:flex;flex-wrap:wrap}.sc-calc-head .btn{flex:1}}</style>
<script>(function(){var d=document.getElementById('sc-calc-display'),expr='',hist=JSON.parse(localStorage.getItem('scCalcHistory')||'[]'),mem=JSON.parse(localStorage.getItem('scCalcMemory')||'{}'),notes=document.getElementById('sc-calc-notes');notes.value=localStorage.getItem('scCalcNotes')||'';notes.oninput=function(){localStorage.setItem('scCalcNotes',notes.value)};function addHist(v){hist.unshift(v);hist=hist.slice(0,100);localStorage.setItem('scCalcHistory',JSON.stringify(hist));renderHist()}function renderHist(){document.getElementById('sc-calc-history').innerHTML=hist.map(function(x){return '<div>'+x+'</div>'}).join('')}function row(container,html){var r=document.createElement('div');r.className='sc-repeat-row';r.innerHTML=html+'<button type="button" class="btn btn-danger btn-sm sc-remove-row"><i class="fa fa-times"></i></button>';document.getElementById(container).appendChild(r)}function input(label,cls,value){return '<div class="form-group"><label>'+label+'</label><input class="form-control '+cls+'" type="number" step="0.01" value="'+(value||'')+'"></div>'}function addWall(){row('sc-wall-rows',input('Length (ft)','wall-l','')+input('Height (ft)','wall-h','8')+input('Spacing (in)','wall-s','16')+'<div class="form-group"><label>Plates</label><select class="form-control wall-p"><option value="3">1 bottom + 2 top</option><option value="2">1 bottom + 1 top</option></select></div><div class="form-group"><label>Result</label><input class="form-control wall-r" readonly></div>')}function addRafter(){row('sc-rafter-rows',input('Run (ft)','raft-run','')+input('Rise (ft)','raft-rise','')+'<div class="form-group"><label>Length</label><input class="form-control raft-result" readonly></div>')}function addAngle(){row('sc-angle-rows',input('Run','angle-run','')+input('Rise','angle-rise','')+'<div class="form-group"><label>Result</label><input class="form-control angle-result" readonly></div>')}function addArea(){row('sc-area-rows',input('Length','area-l','')+input('Width','area-w','')+input('Waste %','area-x','10'))}function addRoof(){row('sc-roof-rows',input('Plane Length (ft)','roof-l','')+input('Slope Width (ft)','roof-w','')+input('Waste %','roof-x','10')+'<div class="form-group"><label>Plane Area</label><input class="form-control roof-r" readonly></div>')}function addDeck(){row('sc-deck-rows',input('Length (ft)','deck-l','')+input('Width (ft)','deck-w','')+input('Joist Spacing (in)','deck-s','16')+input('Railing (LF)','deck-r','0')+input('Openings (LF)','deck-o','0'))}function val(r,c){return parseFloat(r.querySelector('.'+c).value)||0}function showHelp(t){if(window.alert)alert(t)}document.addEventListener('click',function(e){var b=e.target.closest('.sc-remove-row');if(b)b.parentNode.remove();var h=e.target.closest('.sc-help');if(h)showHelp(h.getAttribute('data-help'));});document.querySelectorAll('#sc-calc-modes button').forEach(function(b){b.onclick=function(){document.querySelectorAll('#sc-calc-modes button').forEach(function(x){x.className='btn btn-default'});this.className='btn btn-success active';document.querySelectorAll('#sc-standard,.sc-tool').forEach(function(x){x.classList.add('hide')});document.getElementById('sc-'+this.dataset.mode).classList.remove('hide')}});document.querySelectorAll('.sc-calc-key').forEach(function(b){b.onclick=function(){var k=this.dataset.key;if(k==='C')expr='';else if(k==='⌫')expr=expr.slice(0,-1);else if(k==='='){try{var q=expr.replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-');if(!/^[0-9+\-*/().\s]+$/.test(q))throw 0;var old=expr;expr=String(Function('"use strict";return ('+q+')')());addHist(old+' = '+expr)}catch(x){expr='Error'}}else{if(expr==='Error')expr='';expr+=k}d.value=expr||'0'}});document.querySelectorAll('.sc-mem').forEach(function(b){b.onclick=function(){var s=this.dataset.slot;if(expr){mem[s]=expr;localStorage.setItem('scCalcMemory',JSON.stringify(mem));}else if(mem[s]){expr=mem[s];d.value=expr}}});document.getElementById('sc-copy').onclick=function(){navigator.clipboard&&navigator.clipboard.writeText(d.value)};document.getElementById('sc-paste').onclick=async function(){if(navigator.clipboard){expr=await navigator.clipboard.readText();d.value=expr}};document.getElementById('sc-clear-history').onclick=function(){hist=[];localStorage.removeItem('scCalcHistory');renderHist()};document.getElementById('sc_add_wall').onclick=addWall;document.getElementById('sc_add_rafter').onclick=addRafter;document.getElementById('sc_add_angle').onclick=addAngle;document.getElementById('sc_add_area').onclick=addArea;document.getElementById('sc_add_roof').onclick=addRoof;document.getElementById('sc_add_deck').onclick=addDeck;document.getElementById('sc_calc_walls').onclick=function(){var studs=0,plates=0;document.querySelectorAll('#sc-wall-rows .sc-repeat-row').forEach(function(r){var l=val(r,'wall-l'),h=val(r,'wall-h'),s=val(r,'wall-s')||16,p=val(r,'wall-p')||3,c=Math.ceil(l*12/s)+1;studs+=c;plates+=l*p;r.querySelector('.wall-r').value=c+' studs @ '+h+' ft'});document.getElementById('sc_wall_result').innerHTML='<b>Total studs:</b> '+studs+' &nbsp; <b>Plate lumber:</b> '+plates.toFixed(1)+' LF';addHist('Walls: '+studs+' studs')};document.getElementById('sc_calc_rafters').onclick=function(){document.querySelectorAll('#sc-rafter-rows .sc-repeat-row').forEach(function(r){var x=Math.sqrt(Math.pow(val(r,'raft-run'),2)+Math.pow(val(r,'raft-rise'),2));r.querySelector('.raft-result').value=x.toFixed(3)+' ft';addHist('Rafter '+x.toFixed(3)+' ft')})};document.getElementById('sc_calc_angle').onclick=function(){document.querySelectorAll('#sc-angle-rows .sc-repeat-row').forEach(function(r){var run=val(r,'angle-run'),rise=val(r,'angle-rise'),deg=Math.atan2(rise,run)*180/Math.PI,p=run?rise/run*12:0;r.querySelector('.angle-result').value=deg.toFixed(2)+'° / '+p.toFixed(2)+':12'})};document.getElementById('sc_calc_area').onclick=function(){var total=0;document.querySelectorAll('#sc-area-rows .sc-repeat-row').forEach(function(r){total+=val(r,'area-l')*val(r,'area-w')*(1+val(r,'area-x')/100)});document.getElementById('sc_area_total').textContent=total.toFixed(2);addHist('Area '+total.toFixed(2))};document.getElementById('sc_calc_roofing').onclick=function(){var gross=0;document.querySelectorAll('#sc-roof-rows .sc-repeat-row').forEach(function(r){var a=val(r,'roof-l')*val(r,'roof-w')*(1+val(r,'roof-x')/100);gross+=a;r.querySelector('.roof-r').value=a.toFixed(1)+' sq ft'});var sq=gross/100,valleys=+document.getElementById('sc_roof_valleys').value||0,eaves=+document.getElementById('sc_roof_eaves').value||0,rakes=+document.getElementById('sc_roof_rakes').value||0,drip=(eaves+rakes)*1.1,bundles=Math.ceil(sq*3),under=Math.ceil(gross/200),nails=Math.ceil(sq*320),caps=Math.ceil(gross/200*250),valley=Math.ceil(valleys*3/66.7),tar=Math.max(1,Math.ceil(sq/20));document.getElementById('sc_roof_results').innerHTML='<table class="table table-bordered"><tr><th>Material</th><th>Quantity</th></tr><tr><td>Roofing with waste</td><td>'+gross.toFixed(0)+' sq ft / '+sq.toFixed(2)+' squares</td></tr><tr><td>Shingle bundles</td><td>'+bundles+'</td></tr><tr><td>Underlayment rolls</td><td>'+under+'</td></tr><tr><td>Valley membrane rolls</td><td>'+valley+'</td></tr><tr><td>Drip edge</td><td>'+drip.toFixed(0)+' LF</td></tr><tr><td>Roofing nails</td><td>'+nails+'</td></tr><tr><td>Cap nails</td><td>'+caps+'</td></tr><tr><td>Roof cement</td><td>'+tar+' bucket(s)</td></tr></table>';addHist('Roof '+gross.toFixed(0)+' sq ft')};document.getElementById('sc_calc_deck').onclick=function(){var area=0,joists=0,rail=0;document.querySelectorAll('#sc-deck-rows .sc-repeat-row').forEach(function(r){var l=val(r,'deck-l'),w=val(r,'deck-w'),s=val(r,'deck-s')||16;area+=l*w;joists+=Math.ceil(l*12/s)+1;rail+=Math.max(0,val(r,'deck-r')-val(r,'deck-o'))});document.getElementById('sc_deck_result').innerHTML='<table class="table table-bordered"><tr><th>Deck area</th><td>'+area.toFixed(1)+' sq ft</td></tr><tr><th>Estimated joists</th><td>'+joists+'</td></tr><tr><th>Deck boards at 5.5 in coverage</th><td>'+Math.ceil(area/(5.5/12))+' linear ft</td></tr><tr><th>Railing</th><td>'+rail.toFixed(1)+' linear ft</td></tr><tr><th>Railing posts at 6 ft max</th><td>'+Math.ceil(rail/6)+1+'</td></tr></table>';addHist('Deck '+area.toFixed(1)+' sq ft')};addWall();addRafter();addAngle();addAngle();addArea();addArea();addRoof();addDeck();renderHist()})();</script>
